public final class DetailsActivity extends ThemeActivity implements EngineService.Observer {
 private FavoriteStore favorites;private Button bookmark;private EngineService service;private boolean bound;private Protocol.Item item;private String id;private ImageLoader images;private TextView title,author,rating,description,transferText,unavailable;private Button download;private ProgressBar transfer;private LinearLayout content,below;private ImagePager gallery;private long estimate=-1;
 private final List<Photo> photos=new ArrayList<>();
 private final ServiceConnection connection=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){service=((EngineService.LocalBinder)b).get();bound=true;Protocol.Item cached=service.cachedItem(id);if(cached!=null)item=cached;if(item==null){item=new Protocol.Item(1,getIntent().getStringExtra("title"),"","Addon",false);item.id=id;}render(item);service.observe(DetailsActivity.this);service.details(item,detail->{if(isFinishing()||isDestroyed())return;item=detail;render(detail);if(detail.contentGroups.size()==1)service.estimateSize(detail,size->{if(!isFinishing()&&!isDestroyed()){estimate=size;changed();}});});}public void onServiceDisconnected(ComponentName n){service=null;download.setEnabled(false);transferText.setText("การเชื่อมต่อหยุด กรุณากลับหน้าแรกแล้วลองใหม่");}};
 @Override public void onCreate(Bundle state){super.onCreate(state);id=getIntent().getStringExtra("id");if(id==null||!id.matches("[0-9a-fA-F-]{36}")){finish();return;}try{favorites=Favorites.get(this);item=favorites.get(id);}catch(Exception ignored){}images=new ImageLoader(this,1024);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);
  LinearLayout root=column();root.setBackgroundColor(BG);setContentView(root);root.setOnApplyWindowInsetsListener((v,insets)->{int top,bottom;if(Build.VERSION.SDK_INT>=30){android.graphics.Insets s=insets.getInsets(WindowInsets.Type.systemBars());top=s.top;bottom=s.bottom;}else{top=insets.getSystemWindowInsetTop();bottom=insets.getSystemWindowInsetBottom();}v.setPadding(0,top,0,bottom);return insets;});
  LinearLayout header=row();header.setPadding(dp(8),dp(6),dp(16),dp(6));Button back=button("",false);AppIcons.apply(back,R.drawable.ui_back,TEXT,22);back.setContentDescription("กลับ");header.addView(back,new LinearLayout.LayoutParams(dp(48),dp(48)));back.setOnClickListener(v->finish());title=text(getIntent().getStringExtra("title"),19,TEXT);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);title.setPadding(dp(12),0,dp(8),0);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));bookmark=button("",false);bookmark.setPadding(dp(10),0,dp(10),0);paintBookmark();header.addView(bookmark,new LinearLayout.LayoutParams(dp(48),dp(48)));bookmark.setOnClickListener(v->{if(favorites==null||item==null)return;try{boolean added=favorites.toggle(item);paintBookmark();Toast.makeText(this,added?"เก็บในรายการโปรดแล้ว":"นำออกจากรายการโปรดแล้ว",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"บันทึกรายการโปรดไม่ได้ กรุณาลองใหม่",Toast.LENGTH_LONG).show();}});root.addView(header);
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);content=column();scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));TextView dots=text("",14,RED);dots.setGravity(Gravity.CENTER);dots.setPadding(0,dp(6),0,dp(6));gallery=new ImagePager(this,dots);int width=getResources().getDisplayMetrics().widthPixels;FrameLayout galleryFrame=new FrameLayout(this);galleryFrame.addView(gallery,new FrameLayout.LayoutParams(-1,-1));unavailable=text("ไม่พร้อมใช้งาน รอแป๊บ",12,Color.WHITE);unavailable.setGravity(Gravity.CENTER);unavailable.setBackgroundColor(0xcc0e0f13);galleryFrame.addView(unavailable,new FrameLayout.LayoutParams(-1,dp(34),Gravity.BOTTOM));unavailable.setVisibility(View.GONE);content.addView(galleryFrame,new LinearLayout.LayoutParams(-1,width*9/16));galleryFrame.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->{if(r-l!=or-ol){ViewGroup.LayoutParams lp=galleryFrame.getLayoutParams();lp.height=(r-l)*9/16;galleryFrame.setLayoutParams(lp);}});content.addView(dots);
  LinearLayout body=column();body.setPadding(dp(16),0,dp(16),dp(24));content.addView(body);LinearLayout actions=row();rating=text("",14,TEXT);actions.addView(rating,new LinearLayout.LayoutParams(0,-2,1));download=button("ดาวน์โหลด",true);AppIcons.apply(download,R.drawable.ui_download,ON_ACCENT,18);actions.addView(download,new LinearLayout.LayoutParams(dp(140),dp(52)));actions.setPadding(0,dp(6),0,dp(8));body.addView(actions);download.setOnClickListener(v->{if(service==null||item==null)return;if(service.downloadState(id)==DownloadSession.State.COMPLETE){startActivity(new Intent(this,MainActivity.class).putExtra("tab","files").addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP));finish();}else if(service.isReady()&&service.downloadState(id)!=DownloadSession.State.ACTIVE)service.download(item);});
  transfer=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);transfer.setMax(100);transfer.setProgressTintList(android.content.res.ColorStateList.valueOf(RED));transfer.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(RED));LinearLayout.LayoutParams bar=new LinearLayout.LayoutParams(-1,dp(4));bar.topMargin=dp(12);body.addView(transfer,bar);transferText=text("",12,MUTED);transferText.setPadding(0,dp(7),0,dp(10));body.addView(transferText);author=text("",12,MUTED);author.setPadding(0,dp(4),0,dp(12));body.addView(author);
  TextView descriptionTitle=text("เกี่ยวกับผลงานนี้",16,TEXT);descriptionTitle.setTypeface(Typeface.DEFAULT,Typeface.BOLD);AppIcons.apply(descriptionTitle,R.drawable.ui_info,RED,20);descriptionTitle.setPadding(0,dp(8),0,dp(14));body.addView(descriptionTitle);description=text("กำลังโหลดรายละเอียด…",15,TEXT);description.setPadding(dp(16),dp(16),dp(16),dp(16));description.setLineSpacing(dp(5),1);description.setBackground(round(PANEL));body.addView(description);below=column();below.setPadding(0,dp(16),0,0);body.addView(below);
  bound=bindService(new Intent(this,EngineService.class),connection,BIND_AUTO_CREATE);
 }
 private void paintBookmark(){if(bookmark==null)return;boolean saved=favorites!=null&&favorites.contains(id);AppIcons.apply(bookmark,saved?R.drawable.ui_bookmark_saved:R.drawable.ui_bookmark,saved?RED:TEXT,22);bookmark.setContentDescription(saved?"นำออกจากรายการโปรด":"เก็บในรายการโปรด");bookmark.setEnabled(favorites!=null&&item!=null);}
 private final class Photo {String url;boolean cover;NaturalImage image;int width,height,panOffset;PanoramaView pan;}
 private final class NaturalImage extends ImageView {Photo photo;boolean natural;NaturalImage(){super(DetailsActivity.this);setScaleType(ScaleType.FIT_CENTER);setBackgroundColor(PANEL);setImageResource(R.drawable.rin_icon);setContentDescription("รูปตัวอย่างผลงาน");}@Override protected void onMeasure(int w,int h){if(natural&&photo!=null&&photo.width>0){int width=MeasureSpec.getSize(w);super.onMeasure(MeasureSpec.makeMeasureSpec(width,MeasureSpec.EXACTLY),MeasureSpec.makeMeasureSpec(GalleryRules.naturalHeight(width,photo.width,photo.height),MeasureSpec.EXACTLY));}else super.onMeasure(w,h);}}
 private void render(Protocol.Item detail){paintBookmark();unavailable.setVisibility(detail.available?View.GONE:View.VISIBLE);title.setText(detail.title);AppIcons.apply(rating,R.drawable.ui_star,palette.star,18);rating.setText(detail.rating>=0?String.format(Locale.ROOT,"%.1f",detail.rating)+(detail.ratingCount>0?" ("+detail.ratingCount+")":""):"ยังไม่มีคะแนน");author.setText("โดย "+detail.creator);description.setText(detail.description.isEmpty()?"ยังไม่มีคำอธิบายเพิ่มเติม":detail.description);
  photos.clear();LinkedHashSet<String> urls=new LinkedHashSet<>();if(!detail.imageUrl.isEmpty())urls.add(detail.imageUrl);urls.addAll(detail.screenshots);int count=0;for(String url:urls){if(count++>=24)break;Photo photo=new Photo();photo.url=url;photo.cover=url.equals(detail.imageUrl);photo.image=new NaturalImage();photo.image.photo=photo;photos.add(photo);images.load(url,photo.image,(w,h)->{if(!photos.contains(photo)||isFinishing()||isDestroyed())return;photo.width=w;photo.height=h;renderGallery();});}renderGallery();changed();
 }
 private void renderGallery(){for(Photo p:photos)if(p.pan!=null)p.panOffset=p.pan.getScrollX();below.removeAllViews();List<ImageView> top=new ArrayList<>();for(Photo p:photos){boolean bottom=!p.cover&&GalleryRules.belowDescription(p.width,p.height);p.image.natural=bottom&&!GalleryRules.panorama(p.width,p.height);if(bottom){if(p.image.getParent()!=null)((ViewGroup)p.image.getParent()).removeView(p.image);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(14);if(GalleryRules.panorama(p.width,p.height)){int viewport=Math.max(1,getResources().getDisplayMetrics().widthPixels-dp(32)),height=viewport*9/16;p.pan=new PanoramaView(this);p.image.setScaleType(ImageView.ScaleType.FIT_XY);p.pan.addView(p.image,new android.widget.FrameLayout.LayoutParams(GalleryRules.panoramaWidth(viewport,height,p.width,p.height),height));lp.height=height;below.addView(p.pan,lp);p.pan.post(()->{if(p.pan!=null)p.pan.scrollTo(p.panOffset,0);});TextView tip=text("เลื่อนซ้าย–ขวาเพื่อดูภาพทั้งหมด",11,MUTED);AppIcons.apply(tip,R.drawable.ui_external,MUTED,16);tip.setPadding(0,0,0,dp(16));below.addView(tip);}else{p.pan=null;p.image.setScaleType(ImageView.ScaleType.FIT_CENTER);below.addView(p.image,lp);}}else{p.pan=null;p.image.setScaleType(ImageView.ScaleType.FIT_CENTER);top.add(p.image);}}gallery.pages(top);}
 public void changed(){if(service==null||item==null)return;DownloadSession.State state=service.downloadState(id);boolean active=state==DownloadSession.State.ACTIVE;transfer.setVisibility(active?View.VISIBLE:View.GONE);transferText.setVisibility(active||state==DownloadSession.State.FAILED?View.VISIBLE:View.GONE);
  if(active){download.setCompoundDrawables(null,null,null,null);download.setTextSize(13);int percent=service.downloadPercent;download.setText(service.state.equals("SAVING")?"กำลังบันทึก":percent<0?"กำลังโหลด…":percent+"%");download.setEnabled(false);transfer.setIndeterminate(percent<0);if(percent>=0)transfer.setProgress(percent);transferText.setText(service.transferStage+" • "+TransferMeter.bytes(service.downloadedBytes)+" / "+TransferMeter.bytes(service.downloadTotal));}
  else if(state==DownloadSession.State.COMPLETE){download.setText("เปิด");download.setTextSize(14);AppIcons.apply(download,R.drawable.ui_folder,ON_ACCENT,18);download.setContentDescription("เปิดหน้าดาวน์โหลด");download.setEnabled(true);}
  else{AppIcons.apply(download,R.drawable.ui_download,ON_ACCENT,18);download.setTextSize(13);download.setContentDescription("ดาวน์โหลดผลงาน");download.setText(!item.available?"รอคีย์":state==DownloadSession.State.FAILED?"ลองใหม่":estimate>0?TransferMeter.bytes(estimate):"ดาวน์โหลด");download.setEnabled(item.available&&service.isReady());if(state==DownloadSession.State.FAILED)transferText.setText("ดาวน์โหลดหรือบันทึกไม่ครบ • แตะลองใหม่");}
  if(service.consumeVariantDialog()){String[] labels=service.variantLabels.toArray(new String[0]);if(labels.length==0){service.chooseVariant(1);return;}new AlertDialog.Builder(this).setTitle("เลือกรุ่นของแพ็ก").setItems(labels,(d,w)->service.chooseVariant(w+1)).setCancelable(false).show();}
 }
 private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}private LinearLayout row(){LinearLayout l=column();l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}private TextView text(String s,int n,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(n);t.setTextColor(color);return t;}private Button button(String s,boolean primary){Button b=new Button(this);b.setText(s);b.setTextSize(13);b.setAllCaps(false);b.setTextColor(primary?ON_ACCENT:TEXT);b.setBackground(round(primary?RED:PANEL));b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(10),0,dp(10),0);b.setStateListAnimator(null);AppIcons.ripple(b,round(primary?RED:PANEL));return b;}private GradientDrawable round(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(20));if(color==PANEL)d.setStroke(dp(1),BORDER);return d;}private int dp(float x){return Math.round(x*getResources().getDisplayMetrics().density);}
 @Override protected void onStart(){super.onStart();if(service!=null)service.observe(this);}@Override protected void onStop(){if(service!=null)service.unobserve(this);super.onStop();}@Override protected void onDestroy(){if(service!=null)service.unobserve(this);if(bound)unbindService(connection);if(images!=null)images.close();super.onDestroy();}
}
